<script setup lang="ts">
import { computed, ref } from 'vue';
import type { TaskItem } from '../../composables/useTaskSync';
export type Provider = 'codex' | 'claude_code' | 'antigravity';
export type RunStatus = 'idle' | 'running' | 'completed' | 'failed' | 'cancelled';
type ExecutionPolicy = 'restricted' | 'workspace_write' | 'full_access';
type ApprovalRequest = { id: string; reason: string; requestedAt: string; recommendedPolicy: 'workspace_write' | 'full_access'; diagnosticSummary?: string; diagnosticDetails?: string[] };
const props = defineProps<{ task: TaskItem | null; tasks?: TaskItem[]; provider: Provider; executionPolicy: ExecutionPolicy; phase: string; workspace: string; output: string; running: boolean; runStatus: RunStatus; exitCode: number | null; error: string; approvalRequest: ApprovalRequest | null; diagnosticsLoading: boolean; handoffReviewUrl?: string; epicChildCount?: number; epicCompletedCount?: number; epicAutoContinue?: boolean; epicSequenceRunning?: boolean; autoReviewStatus?: 'idle' | 'reviewing' | 'changes_requested' | 'approved' | 'max_iterations' | 'failed'; autoReviewIteration?: number; autoReviewMaxIterations?: number; autoReviewFeedback?: string; reviewerProvider?: Provider }>();
const emit = defineEmits<{ 'update:provider': [value: Provider]; 'update:executionPolicy': [value: ExecutionPolicy]; chooseWorkspace: []; launch: []; cancel: []; send: [message: string]; handoff: [payload: any]; 'open-hub': []; 'request-approval': []; 'reopen-todo': []; approveRetry: [policy: 'workspace_write' | 'full_access']; dismissApproval: []; timeline: [] }>();
const followUp = ref(''); const showHandoff = ref(false); const summary = ref(''); const changedFiles = ref(''); const tests = ref(''); const testStatus = ref('passed'); const testSummary = ref(''); const commitSha = ref(''); const pullRequestUrl = ref(''); const blockers = ref('');
const dependencyState = computed(() => {
  const dependencies = (props.task?.dependencies || []).map(dependency => ({
    ...dependency,
    depends_on: props.tasks?.find(candidate => candidate.id === dependency.depends_on_task_id) || dependency.depends_on,
  })).filter(dependency => dependency.depends_on);
  const pendingLabels = dependencies
    .filter(dependency => dependency.depends_on?.status !== 'done')
    .map(dependency => dependency.depends_on?.issue_key || `#${dependency.depends_on_task_id}`);
  const dependents = (props.tasks || [])
    .filter(candidate => candidate.id !== props.task?.id)
    .filter(candidate => (candidate.dependencies || []).some(dependency => dependency.depends_on_task_id === props.task?.id))
    .map(candidate => ({ label: candidate.issue_key || `#${candidate.id}`, status: candidate.status }));
  const dependentReconsideration = dependents.filter(candidate => candidate.status !== 'todo');
  return {
    labels: dependencies.map(dependency => dependency.depends_on?.issue_key || `#${dependency.depends_on_task_id}`),
    pendingLabels,
    reconsidered: props.task?.status === 'done' && pendingLabels.length > 0,
    dependents,
    dependentReconsideration,
  };
});
const isEpic = computed(() => props.task?.issue_type === 'epic');
const runnableStatus = computed(() => props.task?.status === 'todo' || props.task?.status === 'in_progress');
const executionBlock = computed(() => {
  if (!props.task) return null;
  if (!runnableStatus.value) {
    if (props.task.status === 'review') return { title: 'Waiting for Hub review', detail: 'This task is in Review. Approve or request changes on Hub before starting another local run.', tone: 'amber' };
    if (props.task.status === 'done') return { title: 'Task already completed', detail: 'This task is complete. Reopen it on Hub before running it again.', tone: 'slate' };
    return { title: 'Execution unavailable', detail: 'The current task status does not allow a local run.', tone: 'slate' };
  }
  if (dependencyState.value.pendingLabels.length) {
    return { title: 'Blocked by prerequisites', detail: `Complete ${dependencyState.value.pendingLabels.join(', ')} before running this task.`, tone: 'amber' };
  }
  if (isEpic.value && !(props.epicChildCount || 0)) {
    return { title: 'Epic has no runnable child tasks', detail: 'Add or unblock a child task on Hub before starting the sequence.', tone: 'slate' };
  }
  return null;
});
const canLaunch = computed(() => Boolean(props.task && props.workspace && !props.running && !props.epicSequenceRunning && runnableStatus.value && !executionBlock.value));
type ActivityKind = 'tool' | 'progress' | 'result' | 'warning' | 'thinking';
type Activity = { kind: ActivityKind; line: string };
type ResponseTurn = { response: string; activity: Activity[]; pending?: boolean; outcome?: Exclude<RunStatus, 'idle'> };
type ActivityGroup = { kind: ActivityKind; lines: string[] };
const classifyActivity = (line: string): ActivityKind => {
  if (/^(?:💭\s*|(?:thinking|reasoning)\s*[:：]|<thinking>)/i.test(line)) return 'thinking';
  if (/\[Executing command\]|⚙|^\$\s/.test(line)) return 'tool';
  if (/✓ Turn completed|✓ Completed|Process exited/.test(line)) return 'result';
  // Source code can legitimately contain Error/Exception/throw. Only explicit
  // runtime diagnostics or non-zero command exits are warnings.
  if (/exit code:\s*(?!0\b)\d+|(?:^|\s)(?:ERROR|FATAL)\s+(?:[\w:.-]+|$)|^(?:stderr:|✕|🛑)\b|process exited \((?!0\))|command failed|failed to execute/i.test(line)) return 'warning';
  return 'progress';
};
const responseTurns = computed<ResponseTurn[]>(() => {
  const turns: ResponseTurn[] = []; let pending: Activity[] = []; let active: ResponseTurn | undefined;
  for (const raw of (props.output || '').split(/\r?\n/)) {
    const line = raw.trimEnd(); if (!line.trim()) continue;
    if (/^💬\s*/.test(line)) { active = { response: line.replace(/^💬\s*/, ''), activity: pending }; pending = []; turns.push(active); continue; }
    const kind = classifyActivity(line);
    if (active && kind === 'progress') { active.response += `\n${line}`; continue; }
    pending.push({ kind, line }); active = undefined;
  }
  if (pending.length && turns.length && !props.running) turns.at(-1)!.activity.push(...pending);
  else if (pending.length || (!turns.length && props.running)) {
    const outcome = props.runStatus === 'idle' ? undefined : props.runStatus;
    const response = props.running ? 'Working…' : props.runStatus === 'failed' ? 'Run failed before a final agent response.' : props.runStatus === 'cancelled' ? 'Run cancelled.' : props.runStatus === 'completed' ? 'Run completed.' : 'Working…';
    turns.push({ response, activity: pending, pending: props.running, outcome });
  }
  return turns;
});
const activityGroups = (turn: ResponseTurn): ActivityGroup[] => (['tool', 'progress', 'thinking', 'warning', 'result'] as ActivityKind[]).map(kind => ({ kind, lines: turn.activity.filter(item => item.kind === kind).map(item => item.line) })).filter(group => group.lines.length);
const activityLabel = (kind: ActivityKind) => ({ tool: 'Tools', progress: 'Progress', thinking: 'Thinking', warning: 'Warnings', result: 'Result' }[kind]);
const activityIcon = (kind: ActivityKind) => ({ tool: '⌘', progress: '◌', thinking: '◒', warning: '!', result: '✓' }[kind]);
const activityTone = (kind: ActivityKind) => ({ tool: 'text-zinc-400', progress: 'text-zinc-400', thinking: 'text-violet-300', warning: 'text-amber-300', result: 'text-emerald-300' }[kind]);
const groupSummary = (group: ActivityGroup) => `${activityIcon(group.kind)} ${activityLabel(group.kind)} · ${group.lines.length} ${group.lines.length === 1 ? 'entry' : 'entries'}`;
const turnSummary = (turn: ResponseTurn) => activityGroups(turn).map(group => `${group.lines.length} ${activityLabel(group.kind).toLowerCase()}`).join(' · ');
const statusLabel = computed(() => ({ idle: 'Idle', running: 'Working', completed: 'Completed', failed: `Failed${props.exitCode === null ? '' : ` · exit ${props.exitCode}`}`, cancelled: 'Cancelled' }[props.runStatus]));
const responseLabel = (turn: ResponseTurn) => turn.pending ? 'Working' : turn.outcome === 'completed' ? 'Run completed' : turn.outcome === 'failed' ? 'Run failed' : turn.outcome === 'cancelled' ? 'Run cancelled' : 'Agent response';
const submit = () => { emit('handoff', { summary: summary.value, changedFiles: changedFiles.value, tests: tests.value, testStatus: testStatus.value, testSummary: testSummary.value, commitSha: commitSha.value, pullRequestUrl: pullRequestUrl.value, blockers: blockers.value }); showHandoff.value = false; };
</script>
<template>
  <section class="flex min-w-0 min-h-0 flex-1 flex-col bg-[#151515] text-zinc-100">
    <header class="border-b border-white/10 px-6 py-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-medium uppercase tracking-wide text-zinc-500">{{ phase }}</p><h2 class="mt-1 text-base font-semibold text-zinc-100">{{ task ? task.title : 'Select a task from the Task queue' }}</h2><p class="mt-1 text-xs text-zinc-400">{{ task ? `${task.issue_key || ''} · ${task.description || 'No task description'}` : 'Choose a task or Epic in the left sidebar, then launch a local agent here.' }}</p><p v-if="isEpic" class="mt-2 text-[11px] font-semibold text-violet-300">Epic sequence · {{ epicCompletedCount || 0 }}/{{ epicChildCount || 0 }} tasks completed · runs one task at a time<span v-if="epicAutoContinue"> and starts the next task after each handoff; Hub review remains required.</span><span v-else> and waits for Hub approval before continuing.</span></p><div v-else-if="task && dependencyState.labels.length" class="mt-2 space-y-0.5 text-[11px]"><p :class="dependencyState.pendingLabels.length ? 'font-semibold text-amber-300' : 'text-zinc-500'">{{ dependencyState.pendingLabels.length ? `Blocked by prerequisites: ${dependencyState.pendingLabels.join(', ')}` : `Prerequisites: ${dependencyState.labels.join(', ')}` }}</p><p v-if="dependencyState.reconsidered" class="font-semibold text-rose-300">Needs review: this task was completed while a prerequisite moved back.</p><p v-if="dependencyState.dependentReconsideration.length" class="font-semibold text-rose-300">Reconsider dependent work: {{ dependencyState.dependentReconsideration.map(item => item.label).join(', ') }}</p><p v-else-if="dependencyState.dependents.length" class="text-zinc-500">Unlocks: {{ dependencyState.dependents.map(item => item.label).join(', ') }}</p></div><div v-if="executionBlock" class="mt-3 inline-flex max-w-full items-start gap-2 rounded-lg border px-3 py-2 text-[11px]" :class="executionBlock.tone === 'amber' ? 'border-amber-700/70 bg-amber-950/30 text-amber-200' : 'border-white/10 bg-black/20 text-zinc-400'"><span class="mt-0.5">{{ executionBlock.tone === 'amber' ? '⏸' : '•' }}</span><span><b class="font-semibold">{{ executionBlock.title }}</b><span class="ml-1 opacity-80">{{ executionBlock.detail }}</span></span></div></div><div class="flex items-center gap-2 overflow-x-auto"><button class="cc-button shrink-0 text-xs" title="View E2E Activity and Audit Timeline" @click="$emit('timeline')">⏱ Timeline</button><select :value="provider" class="cc-select" @change="$emit('update:provider', ($event.target as HTMLSelectElement).value as Provider)"><option value="codex">Codex</option><option value="claude_code">Claude Code</option><option value="antigravity">Antigravity</option></select><select :value="executionPolicy" class="cc-select" title="Execution permission" @change="$emit('update:executionPolicy', ($event.target as HTMLSelectElement).value as ExecutionPolicy)"><option value="restricted">Read only</option><option value="workspace_write">Workspace write</option><option value="full_access">Full access</option></select><button class="cc-button shrink-0" @click="$emit('chooseWorkspace')">{{ workspace ? 'Change repo' : 'Choose repo' }}</button><button class="cc-primary shrink-0" :disabled="!canLaunch" @click="$emit('launch')">{{ isEpic ? 'Run Epic sequence' : 'Launch agent' }}</button></div></div><p class="mt-3 truncate rounded-md bg-black/20 px-3 py-2 font-mono text-xs text-zinc-400">{{ workspace || 'No local repository selected' }}</p><p class="mt-2 text-[11px] text-zinc-500">{{ executionPolicy === 'restricted' ? 'Read-only: Codex cannot edit the repository.' : executionPolicy === 'workspace_write' ? 'Workspace write: Codex is sandboxed to the isolated worktree and asks before escalation.' : 'Full access: a human-approved retry bypasses native sandbox and approval prompts.' }}</p><div v-if="autoReviewStatus && autoReviewStatus !== 'idle'" class="mt-3 rounded-lg border px-3 py-2 text-xs" :class="autoReviewStatus === 'approved' ? 'border-emerald-700/70 bg-emerald-950/30 text-emerald-200' : autoReviewStatus === 'reviewing' ? 'border-sky-700/70 bg-sky-950/30 text-sky-200' : 'border-amber-700/70 bg-amber-950/30 text-amber-200'"><div class="flex items-center justify-between gap-3"><b>{{ autoReviewStatus === 'reviewing' ? `Independent review ${autoReviewIteration || 0}/${autoReviewMaxIterations || 0}` : autoReviewStatus === 'approved' ? 'Independent review approved' : autoReviewStatus === 'changes_requested' ? 'Reviewer requested changes' : autoReviewStatus === 'max_iterations' ? 'Review limit reached' : 'Independent review failed' }}</b><span v-if="reviewerProvider" class="text-[11px] opacity-80">{{ reviewerProvider === 'claude_code' ? 'Claude Code' : reviewerProvider === 'antigravity' ? 'Antigravity' : 'Codex' }}</span></div><p v-if="autoReviewFeedback" class="mt-1 whitespace-pre-wrap leading-5 opacity-90">{{ autoReviewFeedback }}</p></div></header>
    <div v-if="error" class="mx-6 mt-4 rounded-md border border-rose-900/70 bg-rose-950/30 px-3 py-3 text-sm text-rose-200"><div class="flex items-start justify-between gap-3"><span>{{ error }}</span><button v-if="!approvalRequest" class="cc-button shrink-0" :disabled="diagnosticsLoading" @click="$emit('request-approval')">{{ diagnosticsLoading ? 'Checking…' : 'Request human approval' }}</button></div><div v-if="approvalRequest" class="mt-3 rounded border border-amber-700/50 bg-amber-950/30 p-3 text-xs text-amber-100"><p class="font-semibold">Human approval required</p><p class="mt-1 text-amber-100/80">{{ approvalRequest.diagnosticSummary || approvalRequest.reason }}</p><ul v-if="approvalRequest.diagnosticDetails?.length" class="mt-2 list-disc space-y-1 pl-4 text-amber-100/75"><li v-for="detail in approvalRequest.diagnosticDetails" :key="detail">{{ detail }}</li></ul><div class="mt-3 flex flex-wrap gap-2"><button class="cc-button" @click="$emit('approveRetry', 'workspace_write')">Approve workspace-write retry</button><button class="cc-danger" @click="$emit('approveRetry', 'full_access')">Approve full-access retry</button><button class="cc-button" @click="$emit('dismissApproval')">Decline</button></div><p class="mt-2 text-[11px] text-amber-100/60">Requested {{ approvalRequest.requestedAt }}. A full-access retry bypasses Codex sandbox and native approval prompts; it cannot repair a missing sandbox helper.</p></div></div>
    <main class="min-h-0 flex-1 overflow-auto px-6 py-5"><section class="mx-auto w-full max-w-5xl"><div class="mb-4 flex items-center justify-between border-b border-white/10 pb-3 text-xs text-zinc-500"><span>Agent activity</span><span class="inline-flex items-center gap-2" :class="{ 'text-sky-300': runStatus === 'running', 'text-emerald-300': runStatus === 'completed', 'text-rose-300': runStatus === 'failed', 'text-amber-300': runStatus === 'cancelled' }"><i class="h-1.5 w-1.5 rounded-full bg-current" />{{ statusLabel }}</span></div><div v-if="!responseTurns.length" class="py-12 text-center text-sm text-zinc-500"><div v-if="running" class="inline-flex flex-col items-center gap-2"><span class="inline-flex items-center gap-2 font-medium text-sky-400 animate-pulse"><i class="h-2 w-2 rounded-full bg-sky-400"></i>Agent đang thực thi và streaming dữ liệu…</span><span class="text-xs text-zinc-500">Dòng dữ liệu streaming sẽ hiển thị tại đây khi tiến trình output.</span></div><p v-else>Agent activity will appear here.</p></div><div v-else class="relative space-y-6 pl-7 before:absolute before:bottom-0 before:left-1 before:top-1 before:w-px before:bg-white/10"><article v-for="(turn, index) in responseTurns" :key="index" class="relative"><i class="absolute -left-[1.63rem] top-1.5 h-2.5 w-2.5 rounded-full border-2 border-[#151515] bg-zinc-500" :class="{ 'animate-pulse bg-sky-400': turn.pending, 'bg-emerald-400': turn.outcome === 'completed', 'bg-rose-400': turn.outcome === 'failed', 'bg-amber-400': turn.outcome === 'cancelled' }" /><div class="flex items-center justify-between gap-3 text-xs text-zinc-500"><span>{{ responseLabel(turn) }}</span><span>Step {{ index + 1 }}</span></div><pre class="mt-2 whitespace-pre-wrap break-words font-sans text-sm leading-6 text-zinc-100">{{ turn.response }}</pre><details v-if="turn.activity.length" :open="turn.pending || running" class="group mt-3"><summary class="cursor-pointer list-none text-xs text-zinc-500 hover:text-zinc-300"><span class="mr-2 inline-block transition-transform group-open:rotate-90">›</span>{{ turnSummary(turn) }}<span class="ml-2 text-zinc-600">View details</span></summary><div class="mt-3 space-y-2 border-l border-white/10 pl-4"><details v-for="group in activityGroups(turn)" :key="group.kind" :open="running" class="group/nested"><summary class="cursor-pointer list-none text-xs" :class="activityTone(group.kind)"><span class="mr-2 inline-block transition-transform group-open/nested:rotate-90">›</span>{{ groupSummary(group) }}</summary><div class="mt-2 space-y-2 border-l border-white/10 pl-3"><details v-for="(line, lineIndex) in group.lines" :key="lineIndex" :open="running && lineIndex === group.lines.length - 1" class="group/line"><summary class="cursor-pointer list-none truncate font-mono text-[11px] text-zinc-500 hover:text-zinc-300"><span class="mr-2 inline-block transition-transform group-open/line:rotate-90">›</span>{{ line }}</summary><pre class="mt-2 max-h-56 overflow-auto whitespace-pre-wrap break-words rounded bg-black/20 p-3 font-mono text-[11px] leading-5 text-zinc-300">{{ line }}</pre></details></div></details></div></details></article></div></section></main>
     <footer class="border-t border-white/10 px-6 py-4"><div v-if="running" class="flex gap-2"><input v-model="followUp" class="cc-input flex-1" placeholder="Send follow-up to agent" @keyup.enter="followUp && ($emit('send', followUp), followUp = '')"><button class="cc-button" @click="followUp && ($emit('send', followUp), followUp = '')">Send</button><button class="cc-danger" @click="$emit('cancel')">Cancel</button></div><div v-else class="flex flex-wrap items-center justify-between gap-4"><p class="text-xs text-zinc-500">{{ task ? (handoffReviewUrl ? 'Handoff is saved on Hub and waiting for human review.' : 'Next: submit the handoff to move this work into Hub review.') : 'Run complete. Open Hub to review the output or choose the next task.' }}</p><div class="flex flex-wrap items-center gap-2"><a v-if="handoffReviewUrl" :href="handoffReviewUrl" target="_blank" rel="noreferrer" class="cc-primary whitespace-nowrap">Open handoff in Hub ↗</a><button v-if="task" class="cc-primary" @click="showHandoff = !showHandoff">Review & submit handoff</button><button v-else class="cc-primary" @click="$emit('open-hub')">Open Hub for review</button></div></div><form v-if="showHandoff" class="mt-4 grid grid-cols-2 gap-3 rounded-lg bg-black/20 p-4" @submit.prevent="submit"><textarea v-model="summary" class="cc-input col-span-2 min-h-20" placeholder="Summary"></textarea><textarea v-model="changedFiles" class="cc-input min-h-20" placeholder="Changed files, one per line"></textarea><textarea v-model="tests" class="cc-input min-h-20" placeholder="Test command / evidence"></textarea><select v-model="testStatus" class="cc-select"><option value="passed">Passed</option><option value="failed">Failed</option><option value="skipped">Skipped</option></select><input v-model="testSummary" class="cc-input" placeholder="Test result"><input v-model="commitSha" class="cc-input" placeholder="Commit SHA"><input v-model="pullRequestUrl" class="cc-input" placeholder="Pull request URL"><textarea v-model="blockers" class="cc-input col-span-2 min-h-16" placeholder="Blockers (optional)"></textarea><div class="col-span-2 flex justify-end gap-2"><button type="button" class="cc-button" @click="showHandoff = false">Cancel</button><button class="cc-primary">Send to Hub</button></div></form></footer>
    <div v-if="task?.issue_type === 'epic' && task.status === 'review'" class="border-t border-amber-700/50 bg-amber-950/20 px-6 py-3">
      <div class="flex flex-wrap items-center justify-between gap-3 text-xs text-amber-100">
        <span>Epic đang ở Review. Đưa về To do để chạy lại sequence.</span>
        <button class="cc-button shrink-0" @click="$emit('reopen-todo')">Reopen as To do</button>
      </div>
    </div>
   </section>
</template>
